const traditionalMap = Object.fromEntries(pairs.map(pair => [...pair]));
function toTraditional(text) { return [...text].map(char => traditionalMap[char] ?? char).join(''); }
export function t(key, params = {}, locale = 'zh-CN') {
  const base = messages[locale]?.[key] ?? messages['zh-CN'][key] ?? messages['zh-CN'].unknown;
  const text = base.replace(/\{(\w+)\}/g, (_, name) => String(params[name] ?? ''));
  return locale === 'zh-TW' ? toTraditional(text) : text;
}
export function creatureName(id, locale = 'zh-CN') {
  const p = SPECIES[id];
  if (!p) return t('unknown', {}, locale);
  return locale === 'zh-TW' ? p.traditional ?? toTraditional(p.name) : p.name;
}
